import "server-only";

import {readFile} from "node:fs/promises";
import path from "node:path";
import {z} from "zod";

// The compendium is generated by scripts/build_portal_compendium.py in the
// research repository. Every number is read from the census tracker or the
// model/holdout audit artifacts; nothing is hand-entered here. The portal
// re-reads the files on every request, so a regenerated compendium goes live
// without a rebuild.

const datasetSchema = z.object({
  id: z.string().min(1),
  lane: z.string().min(1),
  name: z.string().min(1),
  tier: z.union([z.string(), z.number()]).nullable(),
  accessRoute: z.string().nullable(),
  url: z.string().nullable(),
  licence: z.string().nullable(),
  status: z.string().min(1),
  statusReason: z.string().nullable(),
  bytes: z.number().nullable(),
  receiptPath: z.string().nullable(),
  notes: z.string(),
  updatedAt: z.string().nullable(),
  derivedCovariates: z.array(z.string()),
}).strict();

const covariateSchema = z.object({
  column: z.string().min(1),
  datasetId: z.string().min(1),
  status: z.string().min(1),
  registry: z.string().nullable(),
}).strict();

const datasetsFileSchema = z.object({
  generatedAtUtc: z.string().min(20),
  source: z.string().min(1),
  statusCounts: z.record(z.string(), z.number().int().nonnegative()),
  datasets: z.array(datasetSchema).min(1),
  deadEnds: z.array(z.object({name: z.string(), lane: z.string(), reason: z.string()}).strict()),
  covariates: z.array(covariateSchema),
}).strict();

const thresholdHitSchema = z.object({
  heldOutHits: z.number().int().nonnegative(),
  expectedUnderChance: z.number().nonnegative().nullable(),
  chanceProbability: z.number().min(0).max(1).nullable(),
}).strict();

const holdoutSchema = z.union([
  z.object({
    positiveRecords: z.number().int().positive(),
    clusters: z.number().int().positive().nullable(),
    strictMedianRankPercentile: z.number().min(0).max(1),
    strictMeanRankPercentile: z.number().min(0).max(1),
    thresholdHits: z.record(z.string(), thresholdHitSchema),
  }).strict(),
  z.object({error: z.string()}).strict(),
]);

const modelSummarySchema = z.union([
  z.object({
    featureCount: z.number().int().positive(),
    topWeights: z.array(z.object({column: z.string(), weight: z.number()}).strict()).min(1),
    maxWeight: z.number().positive(),
  }).strict(),
  z.object({error: z.string()}).strict(),
]);

const algorithmSchema = z.object({
  id: z.string().min(1),
  modelId: z.string().min(1),
  title: z.string().min(1),
  role: z.string().min(1),
  registry: z.string().min(1),
  description: z.string().min(1),
  holdout: holdoutSchema,
  model: modelSummarySchema,
  artifacts: z.object({
    rankingCsv: z.string(),
    modelConfig: z.string(),
    clusterHoldoutAudit: z.string(),
  }).strict(),
}).strict();

const algorithmsFileSchema = z.object({
  generatedAtUtc: z.string().min(20),
  method: z.string().min(1),
  evaluation: z.string().min(1),
  algorithms: z.array(algorithmSchema).min(1),
}).strict();

const bandOverlapSchema = z.object({
  shared: z.number().int().nonnegative(),
  onlyPrimary: z.number().int().nonnegative().optional(),
  onlyRefugium: z.number().int().nonnegative().optional(),
  jaccard: z.number().min(0).max(1),
}).strict();

const calibrationReportSchema = z.object({
  generatedAtUtc: z.string().min(20),
  question: z.string().min(1),
  bandComparisonThreshold: z.number().min(0).max(1),
  bands: z.object({
    primaryV5: z.number().int().positive(),
    refugiumCandidate: z.number().int().positive(),
    refugiumVsPrimary: bandOverlapSchema,
    fullRefugiumRerun: z.number().int().positive().optional(),
    fullRerunVsPrimary: bandOverlapSchema.optional(),
    v20Primary: z.number().int().positive().optional(),
    v20PrimaryVsV19Primary: bandOverlapSchema.optional(),
    v21Primary: z.number().int().positive().optional(),
    v21PrimaryVsV20Primary: bandOverlapSchema.optional(),
    v22Primary: z.number().int().positive().optional(),
    v22PrimaryVsV21Primary: bandOverlapSchema.optional(),
    v23Primary: z.number().int().positive().optional(),
    v23PrimaryVsV22Primary: bandOverlapSchema.optional(),
    v24Primary: z.number().int().positive().optional(),
    v24PrimaryVsV23Primary: bandOverlapSchema.optional(),
  }).strict(),
  keyFindings: z.array(z.string()),
}).strict();

export type CompendiumDataset = z.infer<typeof datasetSchema>;
export type CompendiumDatasetsFile = z.infer<typeof datasetsFileSchema>;
export type CompendiumAlgorithm = z.infer<typeof algorithmSchema>;
export type CompendiumAlgorithmsFile = z.infer<typeof algorithmsFileSchema>;
export type CalibrationReport = z.infer<typeof calibrationReportSchema>;

export type AlgorithmHoldout = Extract<CompendiumAlgorithm["holdout"], {positiveRecords: number}>;
export type AlgorithmModelSummary = Extract<CompendiumAlgorithm["model"], {featureCount: number}>;

export function holdoutStats(algorithm: CompendiumAlgorithm): AlgorithmHoldout | null {
  return "positiveRecords" in algorithm.holdout ? algorithm.holdout : null;
}

export function modelStats(algorithm: CompendiumAlgorithm): AlgorithmModelSummary | null {
  return "featureCount" in algorithm.model ? algorithm.model : null;
}

function compendiumDir(): string {
  const researchRoot = path.resolve(
    process.env.QUINKAN_RESEARCH_ROOT ?? "/mnt/donto-data/donto-resources/research/laura-rock-art-discovery",
  );
  return path.join(researchRoot, "outputs", "portal-compendium");
}

async function loadJson(name: string): Promise<unknown> {
  return JSON.parse(await readFile(path.join(compendiumDir(), name), "utf8"));
}

export async function loadCompendiumDatasets(): Promise<CompendiumDatasetsFile> {
  return datasetsFileSchema.parse(await loadJson("datasets.json"));
}

export async function loadCompendiumAlgorithms(): Promise<CompendiumAlgorithmsFile> {
  return algorithmsFileSchema.parse(await loadJson("algorithms.json"));
}

export async function loadCalibrationReport(): Promise<CalibrationReport> {
  return calibrationReportSchema.parse(await loadJson("calibration-report.json"));
}

export function findDataset(file: CompendiumDatasetsFile, id: string): CompendiumDataset | null {
  if (!/^[a-zA-Z0-9._-]+$/.test(id)) return null;
  return file.datasets.find((dataset) => dataset.id === id) ?? null;
}

export function findAlgorithm(file: CompendiumAlgorithmsFile, id: string): CompendiumAlgorithm | null {
  if (!/^[a-zA-Z0-9._-]+$/.test(id)) return null;
  return file.algorithms.find((algorithm) => algorithm.id === id) ?? null;
}

export const datasetStatusLabels: Record<string, string> = {
  downloaded: "Downloaded",
  deferred: "Deferred (route known)",
  deferred_bytes: "Deferred (size)",
  deferred_tooling: "Deferred (tooling)",
  operator_gated: "Needs operator",
  governed: "Governed",
  blocked: "Blocked (door listed)",
  dead_end: "Dead end",
};

export function formatBytes(bytes: number | null): string {
  if (bytes === null || bytes <= 0) return "—";
  const units = ["B", "KB", "MB", "GB"];
  let value = bytes;
  let unit = 0;
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024;
    unit += 1;
  }
  return `${value >= 100 ? Math.round(value) : value.toFixed(1)} ${units[unit]}`;
}
